class ResultSaver(ABC):
    """Abstract sink for processing results."""

    @abstractmethod
    def save(self, result: ProcessingResult) -> None:
        """Persist (or collect) one ProcessingResult."""
        ...


class SidecarResultSaver(ResultSaver):
    """Write each result as a sidecar JSON file next to the source image."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        """Initialise with the given sidecar store (defaults to singleton)."""
        self._writer = store or get_writer()

    def save(self, result: ProcessingResult) -> None:
        data = result.as_dict()
        if result.image_path:
            self._writer.save(result.image_path, data)


class CollectingSidecarSaver(SidecarResultSaver):
    """Like SidecarResultSaver but also accumulates results in a list."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        super().__init__(store=store)
        self.results: List[dict] = []

    def save(self, result: ProcessingResult) -> None:
        super().save(result)
        self.results.append(result.as_dict())


class InMemoryCollector(ResultSaver):
    """Accumulate ProcessingResult objects in memory (no sidecar write)."""

    def __init__(self):
        self.results: List[ProcessingResult] = []

    def save(self, result: ProcessingResult) -> None:
        self.results.append(result)


class NoOpResultSaver(ResultSaver):
    """Discards all results (useful for testing or dry-runs)."""

    def save(self, result: ProcessingResult) -> None:
        pass

